var enc = result.match(/var AesContent = "([^"]+)"/);
if (enc) {
    var crypto = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", "MBvRSW09wFy30Jlb", "p945PZ2aKmFOktpN");
    result = crypto.decryptStr(enc[1]);
}
// 提取 div.content 内容
var m = result.match(/<div class="content">([\s\S]*?)<\/div>\s*<div class="pager">/);
if (m) {
    result = m[1];
}
// 清理广告和样式
result = result.replace(/<style>[\s\S]*?<\/style>/g, "");
result = result.replace(/<div class="ydyym">[\s\S]*?<\/div>/g, "");
result = result.replace(/<a[^>]*data-id[^>]*>[\s\S]*?<\/a>/g, "");
result = result.replace(/最新网址：[^<]*/g, "");
result = result.replace(/永久网址：[^<]*/g, "");
result = result.replace(/<!-- [\s\S]*?-->/g, "");
